import React, {useEffect, useState} from "react";
import { AuthService } from "../../services/AuthApi";
import LoginLayout from "../../components/LoginLayout/LoginLayout";
import {useNavigate} from "react-router-dom";

export default function SignIn() {
    const [error, setError] = useState("");
    const [loading, setLoading] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        async function checkLogin(){
            try {
                const user = await AuthService.myInfo();
                if(user){
                    navigate('/admin/dashboard');
                }
            }catch (err){
                console.log("Error while check cookie: ", (err.response) ? err.response.data : err)
            }
        }
    }, [navigate()]);

    // async function xử lý submit
    async function handleSignIn(user) {
        setLoading(true);
        setError("");

        try {

        } catch (err) {
            console.error("Sign in failed:", err);
            setError(err.error || "Sign in failed");
            alert("Sign in failed");
        } finally {
            setLoading(false);
        }
    }

    return (
        <LoginLayout
            title="Sign In"
            handleOnSubmit={handleSignIn}
            linkHref="/signup"
            submitText="Sign In"
            label="Sign up"
            flag={true}
            linkHref2="/forgetpassword"
            label2="Forget Password"
            error={error}       // truyền lỗi cho LoginLayout hiển thị
            loading={loading}   // truyền loading nếu muốn hiển thị spinner
        />
    );
}
